"rounds": {
  "type": "array",
  "description": "Appended once per revision round. Each round records the prompt files it produced. Frames and critiques are found on disk under frames/round-N/ and critiques/round-N/, not listed here, so two operators working the same round never write the same JSON.",
  "items": {
    "type": "object",
    "required": ["round", "started_at", "prompts"],
    "additionalProperties": false,
    "properties": {

"image_sha256": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "pattern": "^[0-9a-f]{64}$" }
  "description": "SHA-256 of the frame bytes as reviewed. This is what makes the verdict falsifiable: if the file at image_ref no longer hashes to this value, the verdict does not describe it."

"image_ref": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "minLength": 1 }
  "description": "Path to the frame that was critiqued, relative to the output directory root."

"seed": {
  "oneOf": [
    { "type": "null" },
    { "type": "integer" },
    { "type": "string", "minLength": 1 }

"seed": {
  "oneOf": [
    { "type": "null" },
    { "type": "integer" },
    { "type": "string", "minLength": 1 }
  "description": "Generation seed if the generator exposes one. Null when it does not."
